enum anim_flags_t
{
  ANIM_ATTACHED = 0x0010,
  ANIM_TWEEN = 0x0800,
  ANIM_VALID = 0x1000
};

class anim_control_t
{
  float current_time;
  float time_delta;
  float duration;
  float timescale_factor;
  float cntrl_tween_duration;
  float tween_timer;
  unsigned int flags;
  short loop_count;

public:
  bool is_tween() const { return flags & ANIM_TWEEN; }
};

class vector3d
{
  float data[4];
};

class matrix4x4;

class quaternion
{
  float data[4];

public:
  quaternion() {}
  quaternion(const matrix4x4&);
};

class po
{
  float data[16];

public:
  const vector3d& get_abs_position() const;
  void set_position(const vector3d&);
  void fixup();
  const matrix4x4& get_matrix() const;
};

extern const vector3d ZEROVEC;

class po_anim
{
public:
  bool is_valid() const;
  bool has_R() const;
};

class entity_anim;

class entity
{
public:
  virtual bool attach_anim(entity_anim*);
  const po& get_rel_po() const;
  const vector3d& get_rel_position() const;
  bool is_conglom_member() const;
};

class entity_anim
{
  unsigned short flags;
  unsigned short padding;
  void* vtable_padding;

protected:
  entity* ent;
  po_anim* po_anim_ptr;
  void* signal_anim_ptr;
  int priority;
  quaternion tween_quat;
  vector3d rel_pos;

public:
  bool is_attached() const { return flags & ANIM_ATTACHED; }
  bool has_po_anim() const
  {
    return po_anim_ptr != 0 && po_anim_ptr->is_valid();
  }
  virtual void set_flag(anim_flags_t);
  bool attach(const anim_control_t&);
};

bool entity_anim::attach( const anim_control_t& ac )
{
  if ( !is_attached() && ent->attach_anim( this ) )
  {
    if(ac.is_tween() && has_po_anim() && po_anim_ptr->has_R() && ent->is_conglom_member())
    {
      po the_po = ent->get_rel_po();
	  rel_pos = ent->get_rel_position();
      the_po.set_position(ZEROVEC);
      the_po.fixup();
      tween_quat = quaternion(the_po.get_matrix());

    }

    set_flag( ANIM_ATTACHED );
    return true;
  }
  return false;
}
